  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "The closest structural analogue, the phosphoryl-containing ACE inhibitor SQ 29852, has 66% oral bioavailability in humans, directly supporting high F for the query's phosphinyl-phenylbutyl ACE inhibitor scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Quinapril, an ester prodrug ACE inhibitor structurally related to the query, has an absolute oral bioavailability of 51.7% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Perindopril, another ACE inhibitor prodrug, has an absolute oral bioavailability of about 75% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Moexipril, a less well-absorbed ACE inhibitor prodrug, still has 22% oral bioavailability in healthy volunteers, just above the 20% threshold, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Benazepril, an ACE inhibitor prodrug, has an oral bioavailability of 28–37% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a phosphinyl-containing ACE inhibitor prodrug (fosinopril-like). All relevant ACE inhibitor prodrugs with human bioavailability data—SQ 29852 (66%), quinapril (~50%), perindopril (~75%), moexipril (22%), and benazepril (28–37%)—show F ≥ 20%, and the closest analogue is clearly high. Therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability record for the query molecule itself is present in the supplied evidence.",
    "Some records refer to active metabolite exposure rather than prodrug bioavailability, which is less directly applicable to the query.",
    "Several records do not specify absolute bioavailability methodology, though the direction is consistent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

